// Phone controls bridge to the existing, interlocked keyboard command handlers.
const mobile=matchMedia('(pointer:coarse), (max-width:900px)');
const host=document.createElement('section');host.className='mobile-pilot';host.setAttribute('aria-label','Touch pilot');
const water=location.pathname.includes('water-simulation');
host.innerHTML=`<div class="mp-bar"><strong class="mp-status">Loading…</strong><button class="mp-arm">Arm</button><button class="mp-stop">■ STOP</button><button class="mp-more" aria-expanded="false">•••</button></div><div class="mp-pads"><div class="mp-stick" data-stick="move" role="group" aria-label="Movement pad"><span class="mp-north">FORWARD</span><span class="mp-west">←</span><i></i><span class="mp-east">→</span><span class="mp-south">REVERSE</span></div><div class="mp-middle"><button class="mp-camera">◉ View</button>${water?'<button class="mp-recover">Hold 1.5s<br>Deploy</button>':'<button data-key="0">Level</button>'}<small>Release to neutral</small></div><div class="mp-stick" data-stick="turn" role="group" aria-label="Turn and depth pad"><span class="mp-north">ASCEND</span><span class="mp-west">↶</span><i></i><span class="mp-east">↷</span><span class="mp-south">DESCEND</span></div></div><div class="mp-drawer" hidden><button data-key="f">Lights</button><button data-key="k">Accessories</button><button data-key="0">Self-level</button><button data-key="[">Speed −</button><button data-key="]">Speed +</button><button class="mp-expand">Full screen</button><button data-key="q" data-hold>Roll ←</button><button data-key="e" data-hold>Roll →</button><button data-key="t" data-hold>Pitch ↑</button><button data-key="v" data-hold>Pitch ↓</button></div>`;
document.body.append(host);
const $=s=>host.querySelector(s), pointers=new Map(),owners=new Map();let vehicle='',armed=false,ready=false,view=2;
const code=k=>({' ':'Space',Escape:'Escape','[':'BracketLeft',']':'BracketRight'}[k]||(/\d/.test(k)?'Digit'+k:'Key'+k.toUpperCase()));
const emit=(type,k)=>document.body.dispatchEvent(new KeyboardEvent(type,{key:k,code:code(k),bubbles:true,cancelable:true}));
function setKeys(id,next){const prev=owners.get(id)||new Set();for(const k of prev)if(!next.has(k)){prev.delete(k);if(![...owners.entries()].some(([other,keys])=>other!==id&&keys.has(k)))emit('keyup',k);}for(const k of next)if(!prev.has(k)){if(![...owners.values()].some(keys=>keys.has(k)))emit('keydown',k);prev.add(k);}owners.set(id,prev);}
function release(id){setKeys(id,new Set());owners.delete(id);const p=pointers.get(id);if(p){p.el.classList.remove('held');const knob=p.el.querySelector('i');if(knob)knob.style.transform='translate(0,0)';pointers.delete(id);}}
function releaseAll(){for(const id of [...owners.keys(),...pointers.keys()])release(id);}
function tap(k){emit('keydown',k);emit('keyup',k);}
function sourceArm(){return document.querySelector(water?'.manual-arm':'#unlock');}
function sync(){const src=sourceArm();const next=water?(document.querySelector('.deployment-metrics span:last-child b')?.textContent?.trim()||'Loading'):'ROV';const live=!!src&&!src.disabled;const isArmed=src?.getAttribute('aria-pressed')==='true';if(next!==vehicle||(ready&&!live)||(armed&&!isArmed))releaseAll();vehicle=next;ready=live;armed=isArmed;$('.mp-status').textContent=vehicle+' · '+(armed?'ARMED':ready?'SAFE':'WAIT');$('.mp-arm').textContent=armed?'Disarm':'Arm';$('.mp-arm').disabled=!ready;host.classList.toggle('is-armed',armed);host.classList.toggle('is-usv',vehicle==='USV');$('.mp-stick[data-stick="move"] .mp-west').textContent=vehicle==='USV'?'':'←';$('.mp-stick[data-stick="move"] .mp-east').textContent=vehicle==='USV'?'':'→';if(water){const r=document.querySelector('.recovery-hold');$('.mp-recover').disabled=!r||r.disabled;$('.mp-recover').innerHTML='Hold 1.5s<br>'+ (vehicle==='ROV'?'Retrieve':'Deploy');} }
function move(e,p){const r=p.el.getBoundingClientRect(),radius=r.width*.30;let x=(e.clientX-r.left-r.width/2)/radius,y=(e.clientY-r.top-r.height/2)/radius;const len=Math.hypot(x,y);if(len>1){x/=len;y/=len;}p.el.querySelector('i').style.transform=`translate(${x*radius}px,${y*radius}px)`;const keys=new Set();if(ready&&armed){if(p.kind==='move'){if(y<-.3)keys.add('w');if(y>.3)keys.add('s');if(vehicle==='ROV'){if(x<-.3)keys.add('a');if(x>.3)keys.add('d');}}else{if(x<-.3)keys.add(vehicle==='USV'?'a':'z');if(x>.3)keys.add(vehicle==='USV'?'d':'x');if(vehicle==='ROV'){if(y<-.3)keys.add('r');if(y>.3)keys.add('c');}}}setKeys(e.pointerId,keys);}
for(const el of host.querySelectorAll('.mp-stick,[data-hold],.mp-recover')){el.addEventListener('pointerdown',e=>{if(!mobile.matches||el.disabled||[...pointers.values()].some(p=>p.el===el))return;e.preventDefault();el.setPointerCapture(e.pointerId);const p={el,kind:el.dataset.stick};pointers.set(e.pointerId,p);el.classList.add('held');if(p.kind)move(e,p);else setKeys(e.pointerId,new Set([el.dataset.key||'l']));});el.addEventListener('pointermove',e=>{const p=pointers.get(e.pointerId);if(p?.kind)move(e,p);});for(const ev of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(ev,e=>release(e.pointerId));el.addEventListener('contextmenu',e=>e.preventDefault());}
$('.mp-arm').onclick=()=>{releaseAll();sourceArm()?.click();sync();};$('.mp-stop').onclick=()=>{releaseAll();tap('Escape');sync();};$('.mp-more').onclick=()=>{releaseAll();const open=$('.mp-drawer').hidden;$('.mp-drawer').hidden=!open;$('.mp-more').setAttribute('aria-expanded',String(open));};
for(const el of host.querySelectorAll('[data-key]:not([data-hold])'))el.onclick=()=>{releaseAll();tap(el.dataset.key);};
$('.mp-camera').onclick=()=>{releaseAll();if(water){const b=[...document.querySelectorAll('.camera-vehicle button')].find(b=>b.textContent.trim()===vehicle);b?.click();}view=view%4+1;tap(String(view));$('.mp-camera').textContent=['','◉ First','◉ Follow','◉ Wide','◉ Free'][view];};
$('.mp-expand').onclick=async()=>{releaseAll();try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{window.open(location.href,'_blank','noopener');}};
for(const ev of ['blur','pagehide','orientationchange'])window.addEventListener(ev,releaseAll);document.addEventListener('visibilitychange',()=>{if(document.hidden)releaseAll();});mobile.addEventListener('change',releaseAll);setInterval(sync,200);sync();
